/* ===========================================================================
   SECTION 2 - DETERMINISM, STATE, WORLD GENERATION
   =========================================================================== */

/* mulberry32, but the counter lives in the state object so save/load and the
   headless benchmark reproduce the exact same stream. No engine randomness. */
function rndFrom(o){
  var a = o.rng | 0;
  a = (a + 0x6D2B79F5) | 0;
  var t = Math.imul(a ^ (a >>> 15), 1 | a);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  o.rng = a;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function rnd(S){ return rndFrom(S); }
function rint(S,n){ return Math.floor(rnd(S)*n); }
function rrange(S,a,b){ return a + Math.floor(rnd(S)*(b-a+1)); }
function pick(S,arr){ return arr[rint(S,arr.length)]; }

function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function r2(v){ return Math.round(v*100)/100; }
function r1(v){ return Math.round(v*10)/10; }
function fmt(v){ var n = Math.round(v*10)/10; return (Math.abs(n%1)<0.05? String(Math.round(n)) : n.toFixed(1)); }
function sgn(v){ return (v>=0?'+':'') + fmt(v); }
function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

function canon(o){
  if(o===null || typeof o!=='object') return JSON.stringify(o);
  if(Array.isArray(o)) return '['+o.map(canon).join(',')+']';
  var k = Object.keys(o).sort(), out = [];
  for(var i=0;i<k.length;i++) out.push(JSON.stringify(k[i])+':'+canon(o[k[i]]));
  return '{'+out.join(',')+'}';
}
function fnv(str){
  var h = 0x811c9dc5;
  for(var i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return (h>>>0).toString(16).padStart(8,'0');
}
function stateHash(S){ return fnv(canon(S)); }
function clone(S){ return JSON.parse(JSON.stringify(S)); }

function idx(x,y){ return y*MAPW + x; }
function xy(i){ return {x:i%MAPW, y:Math.floor(i/MAPW)}; }
function neighbors(i){
  var p = xy(i), out = [];
  if(p.x>0) out.push(i-1);
  if(p.x<MAPW-1) out.push(i+1);
  if(p.y>0) out.push(i-MAPW);
  if(p.y<MAPH-1) out.push(i+MAPW);
  return out;
}

function logg(S,msg,kind){
  S.log.push({t:S.turn, m:msg, k:kind||''});
  if(S.log.length>500) S.log.splice(0, S.log.length-500);
}

/* ---- world generation -------------------------------------------------- */
function genMap(seed){
  var g = {rng: seed|0};
  var t = new Array(MAPN);
  var i;
  /* base field: ash with rock clumps from two noise passes */
  var h = new Array(MAPN);
  for(i=0;i<MAPN;i++) h[i] = rndFrom(g);
  for(var pass=0;pass<2;pass++){
    var nh = h.slice();
    for(i=0;i<MAPN;i++){
      var ns = neighbors(i), s = h[i], c = 1;
      for(var j=0;j<ns.length;j++){ s += h[ns[j]]; c++; }
      nh[i] = s/c;
    }
    h = nh;
  }
  for(i=0;i<MAPN;i++) t[i] = h[i] > 0.52 ? 'rock' : 'ash';
  /* guaranteed features so no seed is unplayable */
  function scatter(kind, count, allow){
    var placed = 0, guard = 0;
    while(placed<count && guard<600){
      guard++;
      var k = rint(g, MAPN);
      if(allow.indexOf(t[k])<0) continue;
      if(kind==='water' && (k%MAPW===0)) { /* keep a dry column-0 edge sometimes */ }
      t[k] = kind; placed++;
    }
    return placed;
  }
  scatter('water', rrange(g,4,6), ['ash','rock']);
  scatter('vent',  rrange(g,3,5), ['ash','rock']);
  scatter('ruins', rrange(g,6,9), ['ash','rock']);
  /* make sure the minimum viable set exists */
  function count(k){ var c=0; for(var q=0;q<MAPN;q++) if(t[q]===k) c++; return c; }
  var fix = [['water',4],['vent',3],['ruins',5],['ash',12],['rock',6]];
  for(var f=0; f<fix.length; f++){
    var guard2 = 0;
    while(count(fix[f][0]) < fix[f][1] && guard2 < 400){
      guard2++;
      var k2 = rint(g, MAPN);
      if(t[k2]===fix[f][0]) continue;
      if(count(t[k2]) <= 4) continue;
      t[k2] = fix[f][0];
    }
  }
  var map = [];
  for(i=0;i<MAPN;i++) map.push({t:t[i], b:null, dmg:0, w:[]});
  return map;
}

function makeColonist(S, opts){
  opts = opts||{};
  var name = pick(S,FIRSTNAMES)+' '+pick(S,LASTNAMES);
  var job = opts.job || pick(S,JOBKEYS);
  var skill = opts.skill!=null ? opts.skill : rrange(S,1,3);
  var c = {
    id: S.nextId++,
    name: name,
    job: job,
    skill: clamp(skill,1,5),
    xp: 0,
    fatigue: opts.fatigue!=null?opts.fatigue:rrange(S,0,12),
    morale: opts.morale!=null?opts.morale:rrange(S,58,72),
    at: null,
    zero: 0
  };
  return c;
}
function addColonist(S, why, opts){
  var c = makeColonist(S, opts);
  S.pop.push(c);
  S.stats.joined++;
  logg(S, 'JOIN: '+c.name+' ('+JOBS[c.job].n+' skill '+c.skill+') joins the outpost - '+why+'.', 'good');
  return c;
}

function newGame(seed){
  seed = (seed|0) || 1337;
  var S = {
    v: VERSION,
    seed: seed,
    rng: (seed*7919 + 13) | 0,
    turn: 1,
    res: {food:70, water:70, metal:55, power:20, parts:25, scrip:70, ore:15, ash:25, soil:12},
    map: genMap(seed),
    pop: [],
    nextId: 1,
    research: {},
    cooldown: {},
    market: {},
    caravan: {active:false, leaves:0, inv:{}, budget:0, contract:0, next:3},
    log: [],
    ledger: {},
    overflow: {},
    flags: {dust:0, richSeam:0, machine:0, stormWater:0, brownout:0},
    stats: {joined:0, lost:0, storms:0, shortFood:0, shortWater:0, starve:0, built:0, overflowTotal:0, traded:0},
    lastNeeds: {food:0, water:0, foodShort:0, waterShort:0},
    laborUsed: 0,
    pending: null,
    over: null,
    sandbox: false
  };
  for(var i=0;i<TRADEABLE.length;i++) S.market[TRADEABLE[i]] = 1;

  /* starting crew: a guaranteed spread so turn 1 is playable */
  var starters = [
    {job:'farmer',skill:2},{job:'farmer',skill:1},{job:'engineer',skill:2},
    {job:'engineer',skill:1},{job:'scav',skill:2},{job:'medic',skill:1}
  ];
  for(var s=0;s<starters.length;s++) S.pop.push(makeColonist(S, starters[s]));

  /* starting buildings placed deterministically on the best legal tiles */
  placeStart(S,'shelter'); placeStart(S,'shelter');
  placeStart(S,'geo'); placeStart(S,'condenser'); placeStart(S,'sifter');

  logg(S,'The ash stopped falling four days ago. Six of you are still breathing.','hdr');
  logg(S,'Outpost founded on seed '+seed+'. Build, assign, and survive to turn '+WIN_TURN+'.','');
  return S;
}
function placeStart(S,key){
  var best = -1, bestScore = -1;
  for(var i=0;i<MAPN;i++){
    if(!canBuildTerrain(S,i,key)) continue;
    if(S.map[i].b) continue;
    var sc = adjInfo(S,i,key).mult*100 - i*0.01;
    if(sc>bestScore){ bestScore = sc; best = i; }
  }
  if(best<0) return false;
  S.map[best].b = key;
  return true;
}
ASHEOF
