const fs = require('fs');
const path = '/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t24/game.html';
const html = fs.readFileSync(path, 'utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
let src = m[1];
src = src.replace(/tipEl = \$\('tip'\);[\s\S]*$/, '');

const stubEl = () => ({
  style: {}, setAttribute(){}, getAttribute(){return null;}, addEventListener(){},
  focus(){}, select(){}, value: '', innerHTML: '', textContent: '', hidden: true,
  scrollTop: 0, scrollHeight: 0, disabled: false, closest(){ return null; }
});
const stub = `
var document = {
  scripts: [{textContent: SRCTEXT}],
  addEventListener: function(){},
  getElementById: function(){ return STUBEL(); }
};
var window = { addEventListener: function(){}, innerWidth: 1000, innerHeight: 800 };
var setTimeout = function(){};
`;

const fn = new Function('STUBEL', 'SRCTEXT', stub + src + `
; return {newGame:newGame, simulate:simulate, runTests:runTests, stateHash:stateHash,
  endTurn:endTurn, policyTurn:policyTurn, resolveChoice:resolveChoice, autoChoice:autoChoice,
  avgMorale:avgMorale, housing:housing, fmt:fmt, RES:RES, countB:countB, endSummary:endSummary,
  loadState:loadState, viewMap:viewMap, viewPeople:viewPeople, viewResearch:viewResearch,
  viewTrade:viewTrade, viewLog:viewLog, viewDev:viewDev, runBenchmark:runBenchmark, G:G,
  RESKEYS:RESKEYS, builtTiles:builtTiles};
`);

const A = fn(stubEl, 'no engine rng here');
A.G.S = A.newGame(1337);

console.log('=== TESTS ===');
console.log(A.runTests());

console.log('\n=== BENCHMARK DETERMINISM ===');
const b1 = A.runBenchmark();
const b2 = A.runBenchmark();
console.log(b1);
console.log('identical across two runs:', b1 === b2);

console.log('\n=== BALANCE PROBE (greedy policy, 60 turns) ===');
for (const seed of [1337, 42, 2024, 7, 99991]) {
  const S = A.simulate(seed, 60);
  const sum = A.endSummary(S, false, '');
  const needs = S.lastNeeds.foodShort <= 0.05 && S.lastNeeds.waterShort <= 0.05 && S.res.food > 0 && S.res.water > 0;
  const win = S.pop.length >= 12 && needs && A.avgMorale(S) >= 40;
  console.log(`seed ${seed}: pop=${S.pop.length} house=${A.housing(S)} morale=${A.fmt(A.avgMorale(S))} ` +
    `res=${Object.keys(S.research).length}/${A.RESKEYS.length} food=${A.fmt(S.res.food)} water=${A.fmt(S.res.water)} ` +
    `storms=${S.stats.storms} lost=${S.stats.lost} shortF=${S.stats.shortFood} shortW=${S.stats.shortWater} ` +
    `score=${sum.score} WIN=${win}`);
}

console.log('\n=== VIEW RENDER SMOKE TEST ===');
const S = A.newGame(1337);
A.G.S = S;
for (const [name, fnv] of Object.entries({map: A.viewMap, people: A.viewPeople, research: A.viewResearch,
    trade: A.viewTrade, log: A.viewLog, dev: A.viewDev})) {
  try { const out = fnv(S); console.log(`${name}: ok (${out.length} chars)`); }
  catch (e) { console.log(`${name}: THREW ${e.message}`); }
}
A.G.sel = 0;
try { console.log('map w/ selection: ok (' + A.viewMap(S).length + ' chars)'); }
catch (e) { console.log('map w/ selection THREW ' + e.message); }

